const monthlyCashFlow = `-- name: MonthlyCashFlow :many

SELECT to_char(date_trunc('month', e.entry_date), 'YYYY-MM')::text AS month,
       coalesce(sum(e.amount) FILTER (WHERE e.direction = 1), 0)::text AS money_in,
       coalesce(sum(e.amount) FILTER (WHERE e.direction = -1), 0)::text AS money_out,
       coalesce(sum(e.amount) FILTER (WHERE e.direction = 1 AND e.membership_id = $1), 0)::text AS mine,
       count(*) FILTER (WHERE e.direction = 1 AND e.membership_id = $1)::int AS mine_count,
       count(*)::int AS rows
FROM account_entries e
WHERE e.group_id = $2 AND e.voided_at IS NULL AND e.account_transfer_id IS NULL
  AND e.entry_date >= $3
GROUP BY 1
ORDER BY 1
`

